{
  "contract": "GoodMorning",
  "closure": {
    "site_function": "swapBack",
    "site_call": ".addLiquidityETH",
    "functions": [
      "transfer",
      "transferFrom"
    ],
    "justification": "transfer and transferFrom can re-enter during the external call in swapBack as they are public functions related to token transfer and approvals, which may indirectly lead to a swapBack invocation."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "swapBack",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before_addLiquidityETH"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_addLiquidityETH",
      "to_marker": "after_addLiquidityETH"
    },
    "post": {
      "name": "post",
      "from_marker": "after_addLiquidityETH",
      "to_marker": "exit"
    },
    "linearization_point": "after_addLiquidityETH"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of rOwned tokens currently being swapped during the reentrant call.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__rOwned == _totalProportion + inFlight",
    "stable_formula": "_sum__rOwned == _totalProportion",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__rOwned == _totalProportion",
    "rule": "The invariant ensures that the total reflected ownership sum conserves across reentrant calls, accounting for ongoing transactions."
  }
}
